//! The stopwatch's four key pictures, as polygons.
//!
//! Generated by `svg2glyph.py` in the workspace root from the SVGs the
//! pictures came from — do not hand-edit; re-run the script instead. Each
//! table is a list of subpaths, filled together with the even-odd rule, so
//! the flag's inner cut-out and the ring's hole come out empty.
//!
//! Coordinates: the drawing's own box, centred on (0, 0), its height scaled
//! to 1. Multiply by the size the picture should be to place it.
//!
//! A coordinate can land on 0.3183 or 3.1416 by accident; they are points on
//! a ring, not the constants they look like.
#![allow(clippy::approx_constant)]

/// The start key: a filled triangle, `play.svg`. 4 points, 0.866 of the height wide.
pub(crate) const GLYPH_START: &[&[(f32, f32)]] = &[&[
    (0.4330, 0.0000),
    (-0.4330, 0.5000),
    (-0.4330, -0.5000),
    (0.4330, 0.0000),
]];

